{"script":"const items = document.querySelectorAll('a[data-id]');
const list = [];
items.forEach(a => {
  const parent = a.closest('li');
  if (parent) {
    list.push({text: a.textContent.trim(), id: a.getAttribute('data-id')});
  }
});
return JSON.stringify(list, null, 2);
"}

